Method.Source:
/// <summary>
/// Set Item code and account code to All for Unified pricing module
/// </summary>
/// <param name="_sender">PriceDiscAdmTrans data source</param>
/// <param name="_e">Other parameter</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans), FormDataSourceEventType::InitValue)]
public static void PriceDiscAdmTrans_OnInitValue(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    PriceDiscAdmTrans priceDiscAdmTrans = _sender.cursor();

    if (priceDiscAdmTrans.isPricingAttributeEnabled())
    {
        priceDiscAdmTrans.PricingGroupCodeHeader = UPSGroupAll::All;
        priceDiscAdmTrans.PricingGroupCodeLine = UPSGroupAll::All;
        priceDiscAdmTrans.ItemCode = PriceDiscProductCodeType::All;
        priceDiscAdmTrans.AccountCode = PriceDiscPartyCodeType::All;
    }
}

/// <summary>
/// Force write datasource for being able to edit pricing attribute groups
/// </summary>
/// <param name="_sender">PriceDiscAdmTrans data source</param>
/// <param name="_e">Other parameter</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans), FormDataSourceEventType::Created)]
public static void PriceDiscAdmTrans_OnCreated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    PriceDiscAdmTrans priceDiscAdmTrans = _sender.cursor();

    if (priceDiscAdmTrans.isPricingAttributeEnabled())
    {
        _sender.forceWrite(true);
    }
}
